/**
 * Converts a native Promise into a React Suspense-compatible resource.
 */
function wrapPromise(promise) {
  let status = 'pending';
  let result;
  const suspender = promise.then(
    res => {
      status = 'success';
      result = res;
    },
    err => {
      status = 'error';
      result = err;
    }
  );

  return {
    read() {
      if (status === 'pending') {
        throw suspender;
      } else if (status === 'error') {
        throw result;
      } else if (status === 'success') {
        return result;
      }
    }
  };
}
